# ============================================================
# TITAN V10.5 — COGNITIVE NEXUS / EVIDENCE GRAPH
# ------------------------------------------------------------------
# Final arbitration layer above the existing V10 engine.
# Analysis-only: no live order execution and no fabricated market data.
#
# It connects:
# live freshness -> multi-TF spine -> structure/regime -> derivatives
# -> precision -> forecast/patterns -> AI ensemble -> historical outcomes
# -> neural V9 -> Cognitive Nexus -> one canonical decision.
# ============================================================

CNS_VERSION = "TITAN-CNS-10.6-BALANCED"
CNS_HISTORY_LIMIT = 320
CNS_MIN_HISTORY = 5
CNS_PROMOTE_MIN_STRENGTH = 0.40
CNS_PROMOTE_MIN_MARGIN = 0.07
CNS_PROMOTE_MIN_QUALITY = 48.0
CNS_PROMOTE_MIN_DQ = 50.0
CNS_PROMOTE_MIN_NEURAL = 42.0
CNS_PROMOTE_MIN_RR = 1.02
CNS_HARD_CONFLICT = 0.85


class TitanCognitiveNexusV10:
    """Evidence-graph arbitration with Bayesian historical shrinkage.

    Each evidence source is normalized to [-1,+1].
    Historical win rates use Beta(2,2) shrinkage so small samples cannot
    become artificial 0%/100% certainty. Historical data calibrates fresh
    evidence; it never creates a trade by itself.
    """

    TF_WEIGHTS = {"15m": 0.15, "1h": 0.28, "4h": 0.30, "1d": 0.27}

    def _beta_wr(self, wins: float, losses: float) -> float:
        wins = max(0.0, float(wins))
        losses = max(0.0, float(losses))
        return ((wins + 2.0) / (wins + losses + 4.0)) * 100.0

    def _history(self, symbol: str, direction: str, timeframe: str = "") -> dict[str, Any]:
        """Recency-aware historical evidence from evaluated forecasts."""
        out = {
            "samples": 0, "wins": 0, "losses": 0,
            "win_rate": 50.0, "recent_wr": 50.0,
            "confidence": 0.0, "source": "sqlite",
        }
        try:
            params = [symbol, direction]
            sql = (
                "SELECT outcome,created_at FROM forecasts "
                "WHERE symbol=? AND direction=? AND outcome IN ('WIN','LOSS') "
            )
            if timeframe:
                sql += "AND timeframe=? "
                params.append(timeframe)
            sql += "ORDER BY created_at DESC LIMIT ?"
            params.append(CNS_HISTORY_LIMIT)

            with DB_LOCK, db_conn() as con:
                rows = con.execute(sql, params).fetchall()

            if not rows:
                return out

            wins = sum(1 for r in rows if str(r["outcome"]) == "WIN")
            losses = sum(1 for r in rows if str(r["outcome"]) == "LOSS")

            # Recent observations receive more weight, while old observations
            # remain useful for regime-independent baseline calibration.
            now = time.time()
            rw = rl = 0.0
            for i, r in enumerate(rows):
                age_days = max(
                    0.0,
                    (now - safe_float(r["created_at"], now)) / 86400.0,
                )
                w = math.exp(-age_days / 21.0) * (0.985 ** i)
                if str(r["outcome"]) == "WIN":
                    rw += w
                else:
                    rl += w

            out.update({
                "samples": wins + losses,
                "wins": wins,
                "losses": losses,
                "win_rate": round(self._beta_wr(wins, losses), 2),
                "recent_wr": round(self._beta_wr(rw, rl), 2),
                "confidence": round(clamp((wins + losses) / 40.0, 0, 1), 3),
            })
        except Exception as exc:
            LOGGER.debug("CNS history failed %s/%s: %s", symbol, direction, exc)
        return out

    def _ai_reliability(self, symbol: str, direction: str) -> dict[str, Any]:
        """Provider-specific historical alignment from persisted AI votes."""
        out = {
            "samples": 0,
            "aligned": 0,
            "alignment_pct": 50.0,
            "providers": {},
        }
        try:
            with DB_LOCK, db_conn() as con:
                rows = con.execute(
                    "SELECT provider,direction,aligned,created_at "
                    "FROM ai_votes WHERE symbol=? "
                    "ORDER BY created_at DESC LIMIT 160",
                    (symbol,),
                ).fetchall()

            aligned = 0
            total = 0
            providers: dict[str, list[int]] = {}
            for r in rows:
                if str(r["direction"] or "") != direction:
                    continue
                total += 1
                aligned += int(bool(r["aligned"]))
                providers.setdefault(str(r["provider"]), []).append(
                    int(bool(r["aligned"]))
                )

            out["samples"] = total
            out["aligned"] = aligned
            out["alignment_pct"] = round(aligned / total * 100, 1) if total else 50.0
            out["providers"] = {
                k: round(sum(v) / len(v) * 100, 1)
                for k, v in providers.items()
                if v
            }
        except Exception as exc:
            LOGGER.debug("CNS AI reliability failed %s: %s", symbol, exc)
        return out

    def _tf_evidence(
        self, tf_scores: dict[str, Any]
    ) -> tuple[float, float, dict[str, Any]]:
        long_e = short_e = 0.0
        used = 0.0
        rows = {}

        for tf, w in self.TF_WEIGHTS.items():
            if tf not in tf_scores:
                continue
            s = clamp(safe_float(tf_scores.get(tf), 50), 0, 100)
            e = (s - 50.0) / 50.0
            long_e += max(0.0, e) * w
            short_e += max(0.0, -e) * w
            used += w
            rows[tf] = {
                "score": round(s, 1),
                "edge": round(e, 3),
                "weight": w,
            }

        if used <= 0:
            return 0.0, 0.0, {"coherence": 0.0, "frames": rows}

        long_e /= used
        short_e /= used

        active = [v["edge"] for v in rows.values() if abs(v["edge"]) >= 0.08]
        if len(active) <= 1:
            coherence = 0.35 if active else 0.0
        else:
            signs = [1 if x > 0 else -1 for x in active]
            dominant = max(signs.count(1), signs.count(-1))
            coherence = dominant / len(signs)

        return (
            long_e,
            short_e,
            {"coherence": round(coherence, 3), "frames": rows},
        )

    def evaluate(self, item: dict[str, Any]) -> dict[str, Any]:
        symbol = str(item.get("symbol") or "")
        tf_scores = item.get("tf_scores") or {}
        tf_long, tf_short, tf_meta = self._tf_evidence(tf_scores)

        edge = item.get("edge") or {}
        structure = edge.get("structure") or {}
        confluence = edge.get("confluence") or {}
        regime = edge.get("regime") or {}
        precision = item.get("precision") or {}
        neural = (
            item.get("neural_v9")
            or (item.get("fusion") or {}).get("neural_v9")
            or {}
        )
        forecast = item.get("candle_forecast") or {}
        pattern = item.get("patterns") or {}
        ai = edge.get("ai") or {}
        dq = item.get("data_quality") or {}
        ladder = item.get("entry_ladder") or {}

        evidence = []

        def add(
            name: str,
            edge_value: float,
            weight: float,
            quality: float = 1.0,
            note: str = "",
        ):
            evidence.append({
                "name": name,
                "edge": clamp(edge_value, -1, 1),
                "weight": max(0.0, weight),
                "quality": clamp(quality, 0, 1),
                "note": note,
            })

        # 1) Multi-timeframe spine
        add(
            "multi_tf",
            tf_long - tf_short,
            0.22,
            tf_meta["coherence"],
            f"coherence={tf_meta['coherence']:.2f}",
        )

        # 2) Market structure
        sb = str(structure.get("bias") or "")
        sc = clamp(
            safe_float(structure.get("confirmation_score"), 50),
            0, 100,
        )
        structure_edge = 0.0
        if sb == "صعودی":
            structure_edge = (sc - 50) / 50
        elif sb == "نزولی":
            structure_edge = -(sc - 50) / 50
        add("structure", structure_edge, 0.13, sc / 100.0, sb or "neutral")

        # 3) Regime
        rn = str(regime.get("regime") or "").lower()
        reg_edge = 0.0
        if "up" in rn or "bull" in rn:
            reg_edge = 0.45
        elif "down" in rn or "bear" in rn:
            reg_edge = -0.45
        add(
            "regime",
            reg_edge,
            0.08,
            0.85 if reg_edge else 0.45,
            rn or "unknown",
        )

        # 4) Confluence
        cs = clamp(safe_float(confluence.get("score"), 50), 0, 100)
        qbias = str(item.get("bias") or "")
        confluence_edge = 0.0
        if qbias == "صعودی":
            confluence_edge = (cs - 50) / 50
        elif qbias == "نزولی":
            confluence_edge = -(cs - 50) / 50
        add(
            "confluence",
            confluence_edge,
            0.12,
            cs / 100.0,
            f"score={cs:.1f}",
        )

        # 5) Entry precision
        ps = clamp(safe_float(precision.get("score"), 50), 0, 100)
        pside = 1 if qbias == "صعودی" else -1 if qbias == "نزولی" else 0
        add(
            "precision",
            pside * (ps - 50) / 50,
            0.10,
            ps / 100.0,
            str(precision.get("entry_timing") or ""),
        )

        # 6) Probabilistic forecast path
        fb = str(forecast.get("overall_bias") or "")
        fstrength = clamp(
            safe_float(forecast.get("path_strength"), 0) / 40.0,
            0, 1,
        )
        add(
            "forecast",
            fstrength if fb == "صعودی" else -fstrength if fb == "نزولی" else 0,
            0.09,
            1.0 if forecast.get("ok") else 0.0,
            f"corr={safe_float(forecast.get('analogue_corr'), 0):.2f}",
        )

        # 7) Chart pattern
        primary = pattern.get("primary") or {}
        pb = str((primary.get("guide") or {}).get("bias") or "")
        pc = clamp(
            safe_float(primary.get("confidence"), 0) / 100.0,
            0, 1,
        )
        add(
            "pattern",
            pc if pb == "صعودی" else -pc if pb == "نزولی" else 0,
            0.06,
            pc,
            pb or "neutral",
        )

        # 8) Existing neural V9
        nside = str(neural.get("side") or "WAIT")
        nconf = clamp(
            safe_float(neural.get("confidence"), 0) / 100.0,
            0, 1,
        )
        add(
            "neural_v9",
            nconf if nside == "LONG" else -nconf if nside == "SHORT" else 0,
            0.12,
            nconf,
            f"confidence={nconf * 100:.1f}",
        )

        # 9) AI ensemble
        amaj = str(
            ai.get("majority")
            or ai.get("ai_majority")
            or item.get("ai_majority")
            or "WAIT"
        )
        aagree = clamp(
            safe_float(
                ai.get(
                    "majority_agreement",
                    ai.get(
                        "agreement",
                        (item.get("fusion") or {}).get(
                            "ai_agreement", 0
                        ),
                    ),
                ),
                0,
            ) / 100.0,
            0, 1,
        )
        add(
            "ai_ensemble",
            aagree if amaj == "LONG" else -aagree if amaj == "SHORT" else 0,
            0.10,
            aagree,
            f"majority={amaj}",
        )

        # 10) Historical memory
        long_h = self._history(symbol, "صعودی")
        short_h = self._history(symbol, "نزولی")
        hist_edge = (
            (long_h["recent_wr"] - short_h["recent_wr"]) / 50.0
        ) * 0.5
        hist_quality = min(
            1.0,
            (long_h["samples"] + short_h["samples"]) / 30.0,
        )
        add(
            "historical_memory",
            hist_edge,
            0.08,
            hist_quality,
            f"L={long_h['recent_wr']:.1f}%/{long_h['samples']} "
            f"S={short_h['recent_wr']:.1f}%/{short_h['samples']}",
        )

        total_w = sum(
            x["weight"] * max(0.05, x["quality"])
            for x in evidence
        )
        net = (
            sum(
                x["edge"] * x["weight"] * max(0.05, x["quality"])
                for x in evidence
            ) / max(total_w, 1e-9)
        )
        strength = abs(net)
        side = (
            "LONG"
            if net >= CNS_PROMOTE_MIN_MARGIN
            else "SHORT"
            if net <= -CNS_PROMOTE_MIN_MARGIN
            else "WAIT"
        )

        vetoes = []
        dq_score = safe_float(dq.get("score"), 100)

        if dq.get("hard_veto"):
            vetoes.append("data_quality")
        elif dq_score < MIN_DATA_QUALITY_SCORE:
            vetoes.append("data_quality_soft")

        if precision.get("hard_blocks"):
            # Only invalid blocks are hard; others soft
            hard_p = [x for x in precision.get("hard_blocks")[:4] if x == "invalid_price_or_atr"]
            soft_p = [x for x in precision.get("hard_blocks")[:4] if x != "invalid_price_or_atr"]
            if hard_p:
                vetoes.extend([f"precision:{x}" for x in hard_p])
            if soft_p:
                vetoes.extend([f"precision_soft:{x}" for x in soft_p])

        if safe_float(item.get("effective_rr_tp1"), 0) < CNS_MIN_RR:
            # Soft RR below floor — does not block promote alone when other edges strong
            if safe_float(item.get("effective_rr_tp1"), 0) < 0.85:
                vetoes.append("rr")
            else:
                vetoes.append("rr_soft")

        if (
            ladder
            and side in {"LONG", "SHORT"}
            and not ladder.get("passed", True)
        ):
            # Soft ladder unless HTF is strongly opposite
            htf_s = safe_float(ladder.get("htf_score"), 50)
            if (side == "LONG" and htf_s <= 36) or (side == "SHORT" and htf_s >= 64):
                vetoes.append("entry_ladder")
            else:
                vetoes.append("entry_ladder_soft")

        if (
            amaj in {"LONG", "SHORT"}
            and side in {"LONG", "SHORT"}
            and amaj != side
            and aagree >= CNS_HARD_CONFLICT
        ):
            vetoes.append("ai_hard_conflict")

        chosen_hist = (
            long_h if side == "LONG" else short_h
        )
        hist_penalty = (
            chosen_hist["samples"] >= CNS_MIN_HISTORY
            and chosen_hist["recent_wr"] < 42
        )
        if hist_penalty:
            vetoes.append("weak_historical_side")

        # Promotion from WAIT requires independent evidence, not one large score.
        # Soft vetoes (suffix _soft) do not block promotion.
        quality = safe_float(item.get("signal_quality"), 0)
        hard_veto_names = {
            v for v in vetoes
            if not str(v).endswith("_soft") and "soft:" not in str(v)
        }
        promote = (
            side in {"LONG", "SHORT"}
            and strength >= CNS_PROMOTE_MIN_STRENGTH
            and abs(net) >= CNS_PROMOTE_MIN_MARGIN
            and quality >= CNS_PROMOTE_MIN_QUALITY
            and dq_score >= CNS_PROMOTE_MIN_DQ
            and nconf * 100 >= CNS_PROMOTE_MIN_NEURAL
            and safe_float(item.get("effective_rr_tp1"), 0) >= CNS_PROMOTE_MIN_RR
            and tf_meta["coherence"] >= 0.50
            and not hard_veto_names
            and not hist_penalty
        )

        existing = str(item.get("decision_tag") or "WAIT")
        opposite = (
            "SHORT"
            if existing == "LONG"
            else "LONG"
            if existing == "SHORT"
            else ""
        )

        strong_contradiction = (
            existing in {"LONG", "SHORT"}
            and side == opposite
            and strength >= 0.72
            and abs(net) >= 0.28
        )

        # Evidence-strength index; this is NOT a guaranteed win probability.
        confidence = clamp(
            50
            + strength * 45
            + tf_meta["coherence"] * 10
            - len(vetoes) * 8,
            5, 95,
        )
        if chosen_hist["samples"] < CNS_MIN_HISTORY:
            confidence = min(confidence, 82)

        action = "WAIT"
        reason = "شواهد مستقل برای تصمیم جهتی کافی نیست"

        if strong_contradiction:
            reason = "شبکه شواهد مستقل خلاف تصمیم قبلی است"
        elif existing in {"LONG", "SHORT"}:
            action = existing
            reason = "تصمیم موجود توسط شبکه شواهد مستقل بررسی و تأیید شد"
        elif promote:
            action = side
            reason = "فرصت مرزی با اجماع چندلایه و کیفیت داده کافی ارتقا یافت"

        entry_mode = "WAIT"
        if action in {"LONG", "SHORT"}:
            timing = str(precision.get("entry_timing") or "").upper()
            if (
                bool(ladder.get("passed", False))
                and timing in {"READY", "TRIGGER", "OPTIMAL", "GOOD"}
            ):
                entry_mode = "READY"
            else:
                entry_mode = "EARLY"

        return {
            "version": CNS_VERSION,
            "action": action,
            "side": side,
            "entry_mode": entry_mode,
            "net_score": round(net, 4),
            "directional_strength": round(strength, 3),
            "confidence": round(confidence, 1),
            "promoted": bool(promote and existing == "WAIT"),
            "contradiction": bool(strong_contradiction),
            "vetoes": vetoes,
            "reason": reason,
            "tf_coherence": tf_meta["coherence"],
            "tf": tf_meta["frames"],
            "historical": {"long": long_h, "short": short_h},
            "ai_reliability": (
                self._ai_reliability(symbol, amaj)
                if amaj in {"LONG", "SHORT"}
                else {"samples": 0, "aligned": 0, "alignment_pct": 50.0, "providers": {}, "mode": "neutral"}
            ),
            "evidence": evidence,
            "independent_layers": len(
                [e for e in evidence if e["quality"] >= 0.55]
            ),
        }


TITAN_CNS = TitanCognitiveNexusV10()

# Preserve the original V10 analyzer as the audited core. The wrapper is the
# final arbitration layer used by update_cache, so the existing dashboard/API
# contract remains backward compatible.
_analyze_asset_core = analyze_asset


def _v12_parse_price(value: Any) -> float:
    """Parse dashboard-formatted prices without assuming a fixed decimal format."""
    try:
        if isinstance(value, (int, float)):
            return float(value)
        s = str(value or "").replace(",", "").replace(" ", "")
        return float(s)
    except Exception:
        return 0.0


def _v12_rebuild_directional_levels(item: dict[str, Any], direction: str) -> tuple[float, float, float]:
    """Rebuild directional SL/TP when the final arbitration changes a neutral side.

    The core analyzer normally has full ATR/structure context. If a final CNS
    promotion changes WAIT -> LONG/SHORT, this guard reconstructs a conservative
    directional set from the already-computed neutral risk distance instead of
    leaving a bullish signal with bullish TP but a neutral/inconsistent SL.
    """
    price = _v12_parse_price(item.get("price"))
    old_sl = _v12_parse_price(item.get("stop_loss"))
    if price <= 0:
        return 0.0, 0.0, 0.0

    # A neutral core uses approximately 1.6 ATR plus friction. Recover a safe
    # ATR estimate from that distance, with a volatility-based floor.
    neutral_dist = abs(price - old_sl)
    vol_pct = safe_float(item.get("volatility_pct"), 0.0)
    atr_est = max(
        neutral_dist / 1.6 if neutral_dist > 0 else 0.0,
        price * max(vol_pct / 100.0, 0.0025),
        price * 0.0005,
    )

    # Use a conservative local swing proxy. This is deliberately derived from
    # existing validated price/risk data; it never invents a market level.
    swing_low = price - 2.0 * atr_est
    swing_high = price + 2.0 * atr_est

    titan = item.get("titan_analysis") or {}
    adv = titan.get("adv_layers") or {}
    # These values are optional; missing values are allowed.
    vwap = safe_float(adv.get("vwap"), 0.0)
    if direction == "LONG":
        bias = "صعودی"
    elif direction == "SHORT":
        bias = "نزولی"
    else:
        return 0.0, 0.0, 0.0

    sl, tp1, tp2 = calculate_levels(
        price=price,
        atr=atr_est,
        swing_low=swing_low,
        swing_high=swing_high,
        bias=bias,
        vwap=vwap,
        ema20=0.0,
        ema50=0.0,
        structure=(item.get("edge") or {}).get("structure") or {},
        confluence=safe_float((item.get("edge") or {}).get("confluence", {}).get("score"), 50.0),
        order_blocks_fvg=None,
        fibonacci=None,
        forecast=item.get("candle_forecast") or {},
    )
    return float(sl), float(tp1), float(tp2)


def _v12_level_integrity(price: float, sl: float, tp1: float, tp2: float, direction: str) -> dict[str, Any]:
    """Hard validation of direction/levels/RR before a directional signal is exposed."""
    if not all(math.isfinite(x) for x in (price, sl, tp1, tp2)) or price <= 0:
        return {"ok": False, "reason": "invalid_numeric_levels", "rr1": 0.0, "rr2": 0.0}

    risk = abs(price - sl)
    if risk <= price * 0.0002:
        return {"ok": False, "reason": "risk_distance_too_small", "rr1": 0.0, "rr2": 0.0}

    if direction == "LONG":
        orientation = sl < price < tp1 <= tp2
    elif direction == "SHORT":
        orientation = tp2 <= tp1 < price < sl
    else:
        orientation = False

    rr1 = abs(tp1 - price) / risk
    rr2 = abs(tp2 - price) / risk
    ok = bool(orientation and rr1 >= MIN_EFFECTIVE_RR and rr2 >= rr1)
    return {
        "ok": ok,
        "reason": "ok" if ok else ("bad_orientation" if not orientation else "rr_below_threshold"),
        "rr1": round(rr1, 3),
        "rr2": round(rr2, 3),
    }


def _v12_persist_ai_votes(symbol: str, item: dict[str, Any]) -> None:
    """Persist provider votes without creating scan-by-scan duplicate spam."""
    try:
        ai_obj = item.get("ai_opinions") or {}
        titan_side = str(item.get("decision_tag") or "WAIT")
        now = time.time()

        with DB_LOCK, db_conn() as con:
            for provider, raw in ai_obj.items():
                if (
                    provider in {"providers", "ai_status", "internal", "titan"}
                    or not isinstance(raw, str)
                    or not raw.strip()
                ):
                    continue

                vote = extract_structured_ai_vote(raw).get("side", "WAIT")
                recent = con.execute(
                    "SELECT 1 FROM ai_votes "
                    "WHERE symbol=? AND provider=? AND direction=? AND titan_direction=? "
                    "AND created_at>? LIMIT 1",
                    (symbol, provider, vote, titan_side, now - 90.0),
                ).fetchone()
                if recent:
                    continue

                con.execute(
                    "INSERT INTO ai_votes("
                    "created_at,symbol,provider,direction,titan_direction,aligned,latency_ms"
                    ") VALUES(?,?,?,?,?,?,?)",
                    (
                        now,
                        symbol,
                        provider,
                        vote,
                        titan_side,
                        int(vote == titan_side),
                        None,
                    ),
                )
    except Exception as exc:
        LOGGER.debug("V12 AI vote persistence failed %s: %s", symbol, exc)


def _v12_finalize_signal(item: dict[str, Any], cns: dict[str, Any]) -> None:
    """Apply CNS action only when the final public signal remains internally coherent."""
    current = str(item.get("decision_tag") or "WAIT")
    action = str(cns.get("action") or "WAIT")
    fusion = item.setdefault("fusion", {})
    integrity = {
        "version": "V12-CNS-PRO-MAX",
        "core_decision": current,
        "cns_proposal": action,
        "applied": False,
        "level_rebuilt": False,
        "reason": "",
    }

    if action in {"LONG", "SHORT"} and action != current:
        # If CNS proposes a new direction, rebuild levels first.
        sl, tp1, tp2 = _v12_rebuild_directional_levels(item, action)
        price = _v12_parse_price(item.get("price"))
        check = _v12_level_integrity(price, sl, tp1, tp2, action)

        if check["ok"]:
            item["stop_loss"] = smart_format(sl)
            item["tp1"] = smart_format(tp1)
            item["tp2"] = smart_format(tp2)
            item["effective_rr_tp1"] = check["rr1"]
            item["effective_rr_tp2"] = check["rr2"]
            item["rr_tp1"] = check["rr1"]
            item["rr_tp2"] = check["rr2"]
            item["decision_tag"] = action
            item["bias"] = "صعودی" if action == "LONG" else "نزولی"
            item["signal_tag"] = "CNS OPPORTUNITY" if cns.get("promoted") else "CNS CONFIRMED"
            fusion["cns_override"] = True
            fusion["cns_override_reason"] = cns.get("reason")
            integrity.update(applied=True, level_rebuilt=True, reason="directional_levels_rebuilt_and_validated")
        else:
            # Never expose a direction with stale/inconsistent levels.
            integrity["reason"] = f"CNS proposal rejected by level integrity: {check['reason']}"
            fusion["cns_override"] = False
            fusion["cns_override_reason"] = integrity["reason"]

    elif action == "WAIT" and current in {"LONG", "SHORT"}:
        # A strong independent contradiction is materially different from a
        # neutral/soft disagreement. Never keep a directional signal when the
        # evidence graph itself has a high-strength opposite side.
        severe = [v for v in (cns.get("vetoes") or []) if str(v) in {"data_quality", "ai_hard_conflict"}]
        contradiction = bool(cns.get("contradiction"))
        strength = safe_float(cns.get("directional_strength"), 0)
        if contradiction or (severe and strength < 0.35):
            item["decision_tag"] = "WAIT"
            item["bias"] = "خنثی"
            item["signal_tag"] = "CNS BLOCK"
            fusion["cns_override"] = True
            fusion["cns_override_reason"] = cns.get("reason") or "strong independent contradiction"
            integrity.update(applied=True, reason="independent_evidence_blocked_core_direction")
        else:
            fusion["cns_soft_block"] = True
            fusion["cns_override_reason"] = cns.get("reason")
            integrity.update(applied=False, reason="cns_soft_block_direction_kept")

    else:
        integrity["reason"] = "core_and_cns_decision_consistent"

    # Rebuild the canonical object after the final action, not before it.
    item["decision_integrity"] = integrity
    item["canonical_decision"] = {
        "decision": item.get("decision_tag", "WAIT"),
        "bias": item.get("bias", "خنثی"),
        "confidence": cns.get("confidence", 0),
        "signal_quality": item.get("signal_quality", 0),
        "success_probability": item.get("success_probability", 50),
        "cns_version": CNS_VERSION,
        "reason": cns.get("reason", ""),
        "entry_mode": cns.get("entry_mode", "WAIT"),
        "level_integrity": integrity["reason"],
    }


def analyze_asset(symbol: str, btc_trend: str) -> Optional[dict[str, Any]]:
    """V12 CNS PRO MAX public analyzer.

    The V10/V11 core remains the data/indicator/forecast engine. This final
    layer performs evidence arbitration, decision integrity, and learning-memory
    hygiene so no final LONG/SHORT can be emitted with contradictory levels.
    """
    item = _analyze_asset_core(symbol, btc_trend)
    if not item:
        return None

    try:
        cns = TITAN_CNS.evaluate(item)
        item["cognitive_nexus"] = cns
        item.setdefault("fusion", {})["cognitive_nexus"] = cns
        item["cns_action"] = cns.get("action", "WAIT")
        item["cns_confidence"] = cns.get("confidence", 0)
        item["cns_strength"] = cns.get("directional_strength", 0)
        item["entry_mode"] = cns.get("entry_mode", "WAIT")

        _v12_finalize_signal(item, cns)

        # If a promoted signal changed direction, cap displayed confidence until
        # its first live outcome exists. This avoids presenting a fresh promotion
        # as if it were historically proven.
        if cns.get("promoted") and item.get("decision_tag") in {"LONG", "SHORT"}:
            item["signal_quality"] = int(clamp(
                safe_float(item.get("signal_quality"), 0), 0, 92
            ))

        _v12_persist_ai_votes(symbol, item)

        return item

    except Exception as exc:
        LOGGER.exception("V12 CNS arbitration failed for %s: %s", symbol, exc)
        item["decision_integrity"] = {
            "version": "V12-CNS-PRO-MAX",
            "applied": False,
            "reason": "CNS failure; original core decision retained",
        }
        item["cognitive_nexus"] = {
            "version": CNS_VERSION,
            "action": item.get("decision_tag", "WAIT"),
            "confidence": 0,
            "reason": "CNS unavailable; core decision retained",
        }
        return item



# ============================================================
# TITAN V21 TRUST MAX
# Data Integrity + Regime Intelligence + Memory + AI Reliability
# + Probability Calibration + Walk-Forward Audit + Risk Governor
#
# This layer is deliberately additive: the existing V12 dashboard/theme/API
# remain intact. The engine gains a closed-loop audit and trust architecture.
# ============================================================

V21_VERSION = "TITAN-V21-TRUST-MAX-BALANCED"
V21_MIN_DATA_TRUST = 50.0
V21_MIN_SIGNAL_TRUST = 46.0
V21_MIN_HISTORY_SAMPLES = 6
V21_CALIBRATION_MIN_SAMPLES = 10
V21_WALK_FORWARD_MIN_SAMPLES = 16
V21_MAX_STALE_SEC = 60.0
V21_HISTORY_DECAY_DAYS = 45.0


def _v21_now_ts() -> float:
    return time.time()


def _v21_num(x: Any, default: float = 0.0) -> float:
    return safe_float(x, default)


def _v21_direction(x: Any) -> str:
    s = str(x or "").upper().strip()
    return s if s in {"LONG", "SHORT", "WAIT"} else "WAIT"


def _v21_nested(obj: Any, *keys: str, default: Any = None) -> Any:
    cur = obj
    for key in keys:
        if not isinstance(cur, dict):
            return default
        cur = cur.get(key)
    return default if cur is None else cur


class TitanDataIntegrityV21:
    """Independent data-trust gate.

    It never fabricates missing market data. Missing evidence reduces trust and
    can veto a directional decision.
    """

    def evaluate(self, item: dict[str, Any]) -> dict[str, Any]:
        checks = {}
        price = _v21_num(item.get("price"))
        checks["price"] = price > 0

        dq = _v21_num(item.get("data_quality"), 0)
        if dq == 0:
            dq = _v21_num(item.get("data_quality_score"), 0)
        checks["reported_quality"] = dq >= MIN_DATA_QUALITY_SCORE

        # Missing age is unknown, not fresh. Treating it as age=0 silently
        # converted stale/missing live prices into trusted data.
        raw_age = item.get("price_age_sec")
        age = _v21_num(raw_age, -1.0)
        checks["price_fresh"] = 0 <= age <= V21_MAX_STALE_SEC

        tf_scores = item.get("tf_scores") or {}
        valid_tfs = []
        for tf in ("15m", "1h", "4h", "1d"):
            v = _v21_num(tf_scores.get(tf), -1)
            if 0 <= v <= 100:
                valid_tfs.append(tf)
        checks["multi_tf"] = len(valid_tfs) >= 3

        forecast = item.get("candle_forecast") or item.get("forecast") or {}
        checks["forecast"] = bool(forecast.get("ok", False)) and bool(
            forecast.get("candles") or forecast.get("overall_bias") or forecast.get("expected_move_pct") is not None
        )

        derivatives = item.get("derivatives") or {}
        checks["derivatives"] = bool(derivatives) or bool(item.get("oi_delta") is not None)

        passed = sum(bool(v) for v in checks.values())
        completeness = passed / max(len(checks), 1) * 100.0

        # Quality is not allowed to exceed the evidence actually present.
        trust = 0.55 * completeness + 0.45 * min(max(dq, 0), 100)
        trust = clamp(trust, 0, 100)

        hard_fail = []
        if not checks["price"]:
            hard_fail.append("invalid_price")
        if not checks["multi_tf"]:
            hard_fail.append("insufficient_timeframes")
        if age >= 0 and age > V21_MAX_STALE_SEC:
            hard_fail.append("stale_price")
        elif age < 0:
            # Closed-candle price is still real market data; absence of a live
            # tick lowers completeness/trust but is not an invented price.
            pass

        return {
            "version": V21_VERSION,
            "trust": round(trust, 1),
            "completeness": round(completeness, 1),
            "checks": checks,
            "valid_timeframes": valid_tfs,
            "hard_fail": hard_fail,
            "passed": not hard_fail and trust >= V21_MIN_DATA_TRUST,
        }


class TitanRegimeIntelligenceV21:
    """Market-regime classifier using existing item evidence.

    Regime is descriptive; it does not directly force a direction.
    """

    def evaluate(self, item: dict[str, Any]) -> dict[str, Any]:
        tf = item.get("tf_scores") or {}
        vals = [_v21_num(tf.get(k), 50) for k in ("15m", "1h", "4h", "1d")]
        spread = max(vals) - min(vals) if vals else 0
        avg = sum(vals) / max(len(vals), 1)

        edge = item.get("edge") or {}
        regime_obj = edge.get("regime") or {}
        name = str(regime_obj.get("regime") or regime_obj.get("name") or "").lower()

        if "trend" in name or "bull" in name or "bear" in name:
            regime = "TREND"
        elif "range" in name or "side" in name:
            regime = "RANGE"
        elif "break" in name:
            regime = "BREAKOUT"
        elif spread >= 28:
            regime = "TRANSITION"
        elif 43 <= avg <= 57:
            regime = "RANGE"
        else:
            regime = "TREND"

        coherence = 100.0 - clamp(spread * 2.0, 0, 75)
        if regime == "TRANSITION":
            coherence *= 0.75

        return {
            "version": V21_VERSION,
            "regime": regime,
            "tf_average": round(avg, 1),
            "tf_spread": round(spread, 1),
            "coherence": round(coherence, 1),
        }


class TitanHistoricalMemoryV21:
    """Outcome memory with recency weighting and regime/direction separation."""

    def _rows(self, symbol: str, direction: str, limit: int = 400):
        try:
            with DB_LOCK, db_conn() as con:
                return con.execute(
                    "SELECT created_at, outcome, timeframe FROM forecasts "
                    "WHERE symbol=? AND direction=? AND outcome IN ('WIN','LOSS') "
                    "ORDER BY created_at DESC LIMIT ?",
                    (symbol, direction, limit),
                ).fetchall()
        except Exception as exc:
            LOGGER.debug("V21 memory read failed %s: %s", symbol, exc)
            return []

    def evaluate(self, symbol: str, direction: str) -> dict[str, Any]:
        direction = _v21_direction(direction)
        if direction not in {"LONG", "SHORT"}:
            return {"samples": 0, "win_rate": 50.0, "recent_win_rate": 50.0, "confidence": 0, "status": "NEUTRAL"}

        rows = self._rows(symbol, direction)
        if not rows:
            return {"samples": 0, "win_rate": 50.0, "recent_win_rate": 50.0, "confidence": 0, "status": "NO_HISTORY"}

        now = _v21_now_ts()
        weighted_wins = weighted_total = 0.0
        wins = 0
        for row in rows:
            try:
                ts = float(row[0])
            except Exception:
                ts = now
            age_days = max(0.0, (now - ts) / 86400.0) if ts > 1_000_000_000 else 0.0
            w = math.exp(-age_days / V21_HISTORY_DECAY_DAYS)
            outcome = str(row[1] or "").upper()
            weighted_total += w
            if outcome == "WIN":
                weighted_wins += w
                wins += 1

        n = len(rows)
        # Beta(2,2) shrinkage protects against tiny samples.
        posterior = (weighted_wins + 2.0) / (weighted_total + 4.0) if weighted_total else 0.5
        recent = rows[:min(20, n)]
        recent_wins = sum(1 for r in recent if str(r[1]).upper() == "WIN")
        recent_wr = recent_wins / len(recent) if recent else 0.5

        confidence = clamp(
            25.0 + min(55.0, n * 3.0) + abs(posterior - 0.5) * 80.0,
            0, 95
        )
        return {
            "samples": n,
            "wins": wins,
            "losses": n - wins,
            "win_rate": round(posterior * 100, 1),
            "recent_win_rate": round(recent_wr * 100, 1),
            "confidence": round(confidence, 1),
            "status": "ESTABLISHED" if n >= V21_MIN_HISTORY_SAMPLES else "LIMITED",
        }


class TitanAICredibilityV21:
    """Provider-specific historical reliability.

    AI output is evidence, never an unconditional override.
    """

    def evaluate(self, symbol: str, titan_direction: str) -> dict[str, Any]:
        titan_direction = _v21_direction(titan_direction)
        if titan_direction not in {"LONG", "SHORT"}:
            return {"samples": 0, "agreement": 50.0, "providers": {}, "status": "NEUTRAL"}

        try:
            with DB_LOCK, db_conn() as con:
                rows = con.execute(
                    "SELECT provider, direction, aligned FROM ai_votes "
                    "WHERE symbol=? ORDER BY created_at DESC LIMIT 500",
                    (symbol,),
                ).fetchall()
        except Exception as exc:
            LOGGER.debug("V21 AI history failed %s: %s", symbol, exc)
            rows = []

        providers = {}
        total = aligned = 0
        for provider, direction, _stored_titan_direction, is_aligned, _created_at in rows:
            p = str(provider or "").strip().lower()
            if not p:
                continue
            bucket = providers.setdefault(p, {"samples": 0, "aligned": 0})
            bucket["samples"] += 1
            bucket["aligned"] += int(bool(is_aligned))
            total += 1
            aligned += int(bool(is_aligned))

        return {
            "samples": total,
            "agreement": round(aligned / total * 100, 1) if total else 50.0,
            "providers": providers,
            "status": "ESTABLISHED" if total >= V21_MIN_HISTORY_SAMPLES else "LIMITED",
        }


class TitanProbabilityCalibrationV21:
    """Converts historical forecast outcomes into a conservative calibration layer."""

    def evaluate(self, item: dict[str, Any], direction: str) -> dict[str, Any]:
        raw = _v21_num(item.get("success_probability"), 50.0)
        raw = clamp(raw, 1, 99)

        hist = TITAN_MEMORY_V21.evaluate(str(item.get("symbol", "")), direction)
        n = int(hist.get("samples", 0))
        if n < V21_CALIBRATION_MIN_SAMPLES:
            calibrated = 0.70 * raw + 0.30 * 50.0
            status = "INSUFFICIENT_HISTORY"
        else:
            empirical = _v21_num(hist.get("win_rate"), 50.0)
            calibrated = 0.55 * raw + 0.45 * empirical
            status = "CALIBRATED"

        # Never let a small historical sample create extreme certainty.
        cap = 78.0 if n < 30 else 88.0
        calibrated = clamp(calibrated, 22.0, cap)
        return {
            "raw": round(raw, 1),
            "calibrated": round(calibrated, 1),
            "samples": n,
            "status": status,
        }


class TitanWalkForwardAuditV21:
    """Lightweight outcome audit.

    It does not optimize parameters on the same observations it evaluates.
    It reports sample sufficiency rather than pretending a tiny backtest is proof.
    """

    def evaluate(self, symbol: str, direction: str, limit: int = 300) -> dict[str, Any]:
        direction = _v21_direction(direction)
        if direction not in {"LONG", "SHORT"}:
            return {"status": "NEUTRAL", "samples": 0}

        try:
            with DB_LOCK, db_conn() as con:
                rows = con.execute(
                    "SELECT outcome FROM forecasts WHERE symbol=? AND direction=? "
                    "AND outcome IN ('WIN','LOSS') ORDER BY created_at ASC LIMIT ?",
                    (symbol, direction, limit),
                ).fetchall()
        except Exception as exc:
            LOGGER.debug("V21 walk-forward audit failed %s", symbol)
            rows = []

        n = len(rows)
        if n < V21_WALK_FORWARD_MIN_SAMPLES:
            return {
                "status": "INSUFFICIENT",
                "samples": n,
                "oos_win_rate": None,
                "max_losing_streak": None,
            }

        outcomes = [str(r[0]).upper() for r in rows]
        split = max(10, int(n * 0.70))
        test = outcomes[split:]
        wins = sum(1 for x in test if x == "WIN")
        wr = wins / max(len(test), 1) * 100

        streak = best = 0
        for x in test:
            if x == "LOSS":
                streak += 1
                best = max(best, streak)
            else:
                streak = 0

        return {
            "status": "AUDITED",
            "samples": n,
            "train_samples": split,
            "oos_samples": len(test),
            "oos_win_rate": round(wr, 1),
            "max_losing_streak": best,
        }


class TitanRiskGovernorV21:
    """Final independent governor.

    It can downgrade a proposed signal but never upgrades it by itself.
    """

    def evaluate(self, item: dict[str, Any], cns: dict[str, Any],
                 data: dict[str, Any], regime: dict[str, Any],
                 calibration: dict[str, Any], wf: dict[str, Any]) -> dict[str, Any]:
        proposed = _v21_direction(cns.get("action"))
        reasons = []
        score = 100.0

        if data.get("trust", 0) < V21_MIN_DATA_TRUST:
            reasons.append("DATA_TRUST_LOW")
            score -= 35

        if data.get("hard_fail"):
            reasons.extend(data["hard_fail"])
            score -= 30

        if regime.get("regime") == "TRANSITION":
            score -= 10
            reasons.append("REGIME_TRANSITION")

        if proposed in {"LONG", "SHORT"}:
            rr = _v21_num(item.get("effective_rr_tp1"), 0)
            if rr < MIN_EFFECTIVE_RR:
                score -= 30
                reasons.append("RR_LOW")

            cal = _v21_num(calibration.get("calibrated"), 50)
            if cal < 52:
                score -= 20
                reasons.append("CALIBRATION_WEAK")

            if wf.get("status") == "AUDITED" and _v21_num(wf.get("oos_win_rate"), 50) < 45:
                score -= 15
                reasons.append("OOS_WEAK")

        score = clamp(score, 0, 100)
        action = proposed
        if proposed in {"LONG", "SHORT"} and score < V21_MIN_SIGNAL_TRUST:
            action = "WAIT"

        return {
            "version": V21_VERSION,
            "action": action,
            "trust": round(score, 1),
            "reasons": reasons,
            "governed": action != proposed,
        }


class TitanTrustMaxV21:
    """Closed-loop final evidence graph."""

    def evaluate(self, item: dict[str, Any]) -> dict[str, Any]:
        symbol = str(item.get("symbol") or "")
        cns = item.get("cognitive_nexus") or {}
        proposed = _v21_direction(cns.get("action") or item.get("decision_tag"))

        data = TITAN_DATA_V21.evaluate(item)
        regime = TITAN_REGIME_V21.evaluate(item)
        direction = proposed if proposed in {"LONG", "SHORT"} else _v21_direction(item.get("decision_tag"))

        history = (
            TITAN_MEMORY_V21.evaluate(symbol, direction)
            if direction in {"LONG", "SHORT"}
            else {"samples": 0, "win_rate": 50.0, "confidence": 0, "status": "NEUTRAL"}
        )
        ai = TITAN_AI_CRED_V21.evaluate(symbol, direction)
        calibration = TITAN_CALIBRATION_V21.evaluate(item, direction)
        wf = TITAN_WF_V21.evaluate(symbol, direction)
        governor = TITAN_GOVERNOR_V21.evaluate(item, cns, data, regime, calibration, wf)

        # Trust is an evidence quality metric, not a guaranteed probability.
        trust = (
            0.28 * data["trust"]
            + 0.18 * regime["coherence"]
            + 0.18 * _v21_num(cns.get("confidence"), 0)
            + 0.16 * calibration["calibrated"]
            + 0.10 * _v21_num(history.get("confidence"), 0)
            + 0.10 * ai["agreement"]
        )
        trust = clamp(trust, 0, 100)

        final_action = governor["action"]
        if final_action in {"LONG", "SHORT"} and trust < V21_MIN_SIGNAL_TRUST:
            final_action = "WAIT"

        reasons = []
        if not data["passed"]:
            reasons.append("اعتماد داده کافی نیست")
        if governor["governed"]:
            reasons.extend(governor["reasons"])
        if regime["regime"] == "TRANSITION":
            reasons.append("رژیم بازار در حال انتقال است")

        return {
            "version": V21_VERSION,
            "action": final_action,
            "trust": round(trust, 1),
            "proposed_action": proposed,
            "data_integrity": data,
            "regime": regime,
            "historical_memory": history,
            "ai_credibility": ai,
            "calibration": calibration,
            "walk_forward": wf,
            "risk_governor": governor,
            "reasons": list(dict.fromkeys(reasons)),
            "audit_note": "Trust is evidence quality, not a profit guarantee.",
        }


TITAN_DATA_V21 = TitanDataIntegrityV21()
TITAN_REGIME_V21 = TitanRegimeIntelligenceV21()
TITAN_MEMORY_V21 = TitanHistoricalMemoryV21()
TITAN_AI_CRED_V21 = TitanAICredibilityV21()
TITAN_CALIBRATION_V21 = TitanProbabilityCalibrationV21()
TITAN_WF_V21 = TitanWalkForwardAuditV21()
TITAN_GOVERNOR_V21 = TitanRiskGovernorV21()
TITAN_TRUST_V21 = TitanTrustMaxV21()


# Preserve the V12 public analyzer and put Trust Max above it.
_analyze_asset_v12 = analyze_asset


def analyze_asset(symbol: str, btc_trend: str) -> Optional[dict[str, Any]]:
    item = _analyze_asset_v12(symbol, btc_trend)
    if not item:
        return None

    try:
        trust = TITAN_TRUST_V21.evaluate(item)
        item["trust_max_v21"] = trust
        item.setdefault("fusion", {})["trust_max_v21"] = trust

        # V21 is a governor. V28.4: only hard data failure kills direction;
        # otherwise keep LONG/SHORT and attach risk reasons.
        action = trust["action"]
        hard_data = bool((trust.get("data_integrity") or {}).get("hard_fail"))
        if action == "WAIT" and str(item.get("decision_tag")) in {"LONG", "SHORT"}:
            if hard_data or safe_float(trust.get("trust"), 100) < 35:
                item["decision_tag"] = "WAIT"
                item["bias"] = "خنثی"
                item["signal_tag"] = "V21 RISK GOVERNOR"
                item["entry_mode"] = "WAIT"
                item["fusion"]["v21_override"] = True
                item["fusion"]["v21_reason"] = trust["reasons"]
            else:
                item["fusion"]["v21_soft"] = True
                item["fusion"]["v21_reason"] = trust["reasons"]
                item["signal_tag"] = str(item.get("signal_tag") or "CONFIRMED SETUP")
                if item.get("signal_quality") is not None:
                    item["signal_quality"] = int(min(safe_float(item.get("signal_quality"), 50), 74))

        item["canonical_decision"] = {
            **(item.get("canonical_decision") or {}),
            "decision": item.get("decision_tag", "WAIT"),
            "bias": item.get("bias", "خنثی"),
            "trust_max": trust["trust"],
            "trust_version": V21_VERSION,
            "risk_governor": trust["risk_governor"],
            "data_integrity": trust["data_integrity"],
            "regime": trust["regime"],
            "calibration": trust["calibration"],
        }

        # Expose a compact audit object for the dashboard without changing the UI.
        item["decision_audit"] = {
            "final": item.get("decision_tag", "WAIT"),
            "trust": trust["trust"],
            "data_trust": trust["data_integrity"]["trust"],
            "regime": trust["regime"]["regime"],
            "calibrated_probability": trust["calibration"]["calibrated"],
            "history_samples": trust["historical_memory"].get("samples", 0),
            "oos_status": trust["walk_forward"].get("status"),
            "reasons": trust["reasons"],
        }

        return item
    except Exception as exc:
        LOGGER.exception("V21 Trust Max failed for %s: %s", symbol, exc)
        return item


# ============================================================
# TITAN V22 — ADAPTIVE OPPORTUNITY & SELF-LEARNING ENGINE
#
# Goal:
#   1) Avoid arbitrary WAIT.
#   2) Avoid arbitrary LONG/SHORT.
#   3) Preserve a real directional signal when evidence is sufficient.
#   4) Surface strong pre-trigger opportunities as EARLY/WATCH instead of
#      hiding them behind WAIT.
#   5) Learn from realized outcomes and recalibrate thresholds/AI influence.
#   6) Produce a complete reason tree for every final decision.
#
# This layer is analysis-only. It never executes orders and never invents
# market data, levels, or outcomes.
# ============================================================

V22_VERSION = "TITAN-V22-ADAPTIVE-OPPORTUNITY-BALANCED"
V22_JOURNAL_COOLDOWN = 90.0
V22_CANDIDATE_MEMORY_MINUTES = 24.0
V22_PROMOTE_SCORE = 56.0
V22_STRONG_TRIGGER_SCORE = 64.0
V22_EARLY_SCORE = 48.0
V22_WATCH_SCORE = 40.0
V22_MIN_DATA = 48.0
V22_MIN_QUALITY = 44.0
V22_MIN_NEURAL = 40.0
V22_MIN_RR = 1.02
V22_MIN_AI_AGREEMENT = 48.0
V22_MAX_AI_CONFLICT = 92.0
V22_MAX_HARD_VETOES = 1


def _v22_init_tables() -> None:
    try:
        with DB_LOCK, db_conn() as con:
            con.execute("""
                CREATE TABLE IF NOT EXISTS decision_journal_v22(
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    created_at REAL NOT NULL,
                    symbol TEXT NOT NULL,
                    decision TEXT NOT NULL,
                    candidate_side TEXT DEFAULT 'WAIT',
                    opportunity_state TEXT DEFAULT 'NO_EDGE',
                    opportunity_score REAL DEFAULT 0,
                    trust REAL DEFAULT 0,
                    quality REAL DEFAULT 0,
                    ai_majority TEXT DEFAULT 'WAIT',
                    ai_agreement REAL DEFAULT 0,
                    regime TEXT DEFAULT '',
                    reason_json TEXT DEFAULT '{}',
                    outcome TEXT DEFAULT 'PENDING'
                )
            """)
            con.execute("CREATE INDEX IF NOT EXISTS idx_v22_journal_symbol ON decision_journal_v22(symbol, created_at)")
            con.execute("CREATE INDEX IF NOT EXISTS idx_v22_journal_outcome ON decision_journal_v22(outcome, created_at)")
            con.execute("""
                CREATE TABLE IF NOT EXISTS v22_learning_state(
                    state_key TEXT PRIMARY KEY,
                    updated_at REAL NOT NULL,
                    payload TEXT NOT NULL
                )
            """)
            con.execute("""
                CREATE TABLE IF NOT EXISTS v22_candidate_state(
                    symbol TEXT PRIMARY KEY,
                    side TEXT DEFAULT 'WAIT',
                    first_seen REAL DEFAULT 0,
                    last_seen REAL DEFAULT 0,
                    streak INTEGER DEFAULT 0,
                    best_score REAL DEFAULT 0,
                    last_reason TEXT DEFAULT ''
                )
            """)
    except Exception as exc:
        LOGGER.warning("V22 table initialization failed: %s", exc)


_v22_init_tables()


class TitanLearningEngineV22:
    """Outcome-driven calibration.

    It deliberately uses shrinkage and minimum samples. A tiny winning streak
    cannot make the engine aggressively lower its thresholds.
    """

    def _rows(self, symbol: str = "", direction: str = ""):
        sql = (
            "SELECT id,symbol,direction,outcome,score,alignment,ai_majority,"
            "ai_agreement,fused_score,success_prob,created_at "
            "FROM forecasts WHERE outcome IN ('WIN','LOSS')"
        )
        params = []
        if symbol:
            sql += " AND symbol=?"
            params.append(symbol)
        if direction:
            sql += " AND direction=?"
            params.append(direction)
        sql += " ORDER BY created_at DESC LIMIT 1200"
        try:
            with DB_LOCK, db_conn() as con:
                return con.execute(sql, params).fetchall()
        except Exception as exc:
            LOGGER.debug("V22 learning rows failed: %s", exc)
            return []

    @staticmethod
    def _beta(wins: float, losses: float) -> float:
        return (wins + 2.0) / (wins + losses + 4.0) * 100.0

    def side_profile(self, symbol: str, side: str) -> dict[str, Any]:
        db_side = "صعودی" if side == "LONG" else "نزولی"
        rows = self._rows(symbol, db_side)
        n = len(rows)
        wins = sum(1 for r in rows if str(r["outcome"]) == "WIN")
        losses = n - wins
        recent = rows[:20]
        rw = sum(1 for r in recent if str(r["outcome"]) == "WIN")
        wr = self._beta(wins, losses)
        recent_wr = self._beta(rw, max(0, len(recent) - rw))

        # Calibration: are high model probabilities actually associated with wins?
        high_p = [r for r in rows if safe_float(r["success_prob"], 0) >= 60]
        high_p_wr = (
            self._beta(
                sum(1 for r in high_p if str(r["outcome"]) == "WIN"),
                sum(1 for r in high_p if str(r["outcome"]) == "LOSS"),
            )
            if high_p else 50.0
        )

        # AI ensemble accuracy for this side.
        ai_rows = [
            r for r in rows
            if str(r["ai_majority"] or "").upper() in {side, "LONG" if side == "LONG" else "SHORT"}
        ]
        ai_w = sum(1 for r in ai_rows if str(r["outcome"]) == "WIN")
        ai_l = sum(1 for r in ai_rows if str(r["outcome"]) == "LOSS")
        ai_wr = self._beta(ai_w, ai_l) if ai_rows else 50.0

        # Stable adaptive threshold shift. Positive means be stricter.
        shift = 0.0
        if n >= 10:
            if recent_wr < 45:
                shift += min(4.0, (45.0 - recent_wr) * 0.18)
            elif recent_wr > 61:
                shift -= min(3.0, (recent_wr - 61.0) * 0.12)
            if high_p_wr < 45:
                shift += 1.5
            elif high_p_wr > 62:
                shift -= 1.0
        return {
            "samples": n,
            "wins": wins,
            "losses": losses,
            "win_rate": round(wr, 1),
            "recent_win_rate": round(recent_wr, 1),
            "high_probability_wr": round(high_p_wr, 1),
            "ai_aligned_wr": round(ai_wr, 1),
            "ai_samples": len(ai_rows),
            "threshold_shift": round(shift, 2),
            "confidence": round(min(1.0, n / 40.0), 3),
        }

    def global_profile(self) -> dict[str, Any]:
        rows = self._rows()
        n = len(rows)
        wins = sum(1 for r in rows if str(r["outcome"]) == "WIN")
        losses = n - wins
        ai_rows = [r for r in rows if str(r["ai_majority"] or "").upper() in {"LONG", "SHORT"}]
        ai_w = sum(1 for r in ai_rows if str(r["outcome"]) == "WIN")
        ai_l = sum(1 for r in ai_rows if str(r["outcome"]) == "LOSS")
        return {
            "samples": n,
            "win_rate": round(self._beta(wins, losses), 1),
            "ai_win_rate": round(self._beta(ai_w, ai_l), 1) if ai_rows else 50.0,
            "ai_samples": len(ai_rows),
        }


class TitanOpportunityEngineV22:
    """Balances action vs patience using a two-threshold + persistence model."""

    def _ai(self, item: dict[str, Any]) -> tuple[str, float]:
        edge_ai = (item.get("edge") or {}).get("ai") or {}
        fusion = item.get("fusion") or {}
        majority = str(
            edge_ai.get("majority")
            or edge_ai.get("ai_majority")
            or fusion.get("ai_majority")
            or "WAIT"
        ).upper()
        agreement = safe_float(
            edge_ai.get("majority_agreement")
            or edge_ai.get("agreement")
            or fusion.get("ai_agreement"),
            0,
        )
        return majority if majority in {"LONG", "SHORT", "WAIT"} else "WAIT", clamp(agreement, 0, 100)

    def _candidate_edges(self, item: dict[str, Any]) -> dict[str, float]:
        tf = item.get("tf_scores") or {}
        tf_long = tf_short = 0.0
        weights = {"15m": 0.18, "1h": 0.30, "4h": 0.28, "1d": 0.24}
        used = 0.0
        for k, w in weights.items():
            if k not in tf:
                continue
            e = (safe_float(tf.get(k), 50) - 50) / 50
            if e > 0:
                tf_long += e * w
            elif e < 0:
                tf_short += -e * w
            used += w
        if used:
            tf_long /= used
            tf_short /= used

        structure = (item.get("edge") or {}).get("structure") or {}
        confluence = (item.get("edge") or {}).get("confluence") or {}
        precision = item.get("precision") or {}
        neural = item.get("neural_v9") or {}
        fc = item.get("candle_forecast") or {}
        patterns = item.get("patterns") or {}
        primary = patterns.get("primary") or {}
        guide = primary.get("guide") or {}

        struct_side = str(structure.get("bias") or "")
        struct_sc = safe_float(structure.get("confirmation_score"), 50)
        conf_sc = safe_float(confluence.get("score"), 50)
        prec_sc = safe_float(precision.get("score"), 50)
        nside = str(neural.get("side") or "WAIT")
        nconf = safe_float(neural.get("confidence"), 0) / 100
        fb = str(fc.get("overall_bias") or "")
        fs = clamp(safe_float(fc.get("path_strength"), 0) / 40, 0, 1)
        pb = str(guide.get("bias") or "")
        pc = clamp(safe_float(primary.get("confidence"), 0) / 100, 0, 1)

        def side_score(side: str) -> float:
            s = 0.0
            # TF spine
            s += (tf_long if side == "LONG" else tf_short) * 100 * .25
            # Structure
            if (side == "LONG" and struct_side == "صعودی") or (side == "SHORT" and struct_side == "نزولی"):
                s += max(0, struct_sc - 50) * .18
            # Confluence follows current bias but is still a useful independent vote.
            current_bias = str(item.get("bias") or "")
            if (side == "LONG" and current_bias == "صعودی") or (side == "SHORT" and current_bias == "نزولی"):
                s += max(0, conf_sc - 50) * .14
            # Precision
            s += max(0, prec_sc - 50) * .10
            # Neural
            if nside == side:
                s += nconf * 12
            # Forecast
            if (side == "LONG" and fb == "صعودی") or (side == "SHORT" and fb == "نزولی"):
                s += fs * 8
            # Pattern
            if (side == "LONG" and pb == "صعودی") or (side == "SHORT" and pb == "نزولی"):
                s += pc * 5
            return clamp(s, 0, 100)

        return {"LONG": side_score("LONG"), "SHORT": side_score("SHORT")}

    def _persistence(self, symbol: str, side: str, score: float) -> dict[str, Any]:
        # WAIT is not a directional candidate and must not build persistence
        # that can later be mistaken for an entry setup.
        if side not in {"LONG", "SHORT"}:
            return {"streak": 0, "age_min": 0.0, "persistent": False}
        now = time.time()
        try:
            with DB_LOCK, db_conn() as con:
                row = con.execute(
                    "SELECT * FROM v22_candidate_state WHERE symbol=?",
                    (symbol,),
                ).fetchone()
                if not row:
                    con.execute(
                        "INSERT INTO v22_candidate_state(symbol,side,first_seen,last_seen,streak,best_score,last_reason) VALUES(?,?,?,?,?,?,?)",
                        (symbol, side, now, now, 1, score, ""),
                    )
                    return {"streak": 1, "age_min": 0.0, "persistent": False}
                old_side = str(row["side"] or "WAIT")
                last = safe_float(row["last_seen"], now)
                age_min = max(0.0, (now - last) / 60.0)
                if old_side == side and age_min <= V22_CANDIDATE_MEMORY_MINUTES:
                    streak = int(row["streak"] or 0) + 1
                    first = safe_float(row["first_seen"], now)
                else:
                    streak = 1
                    first = now
                con.execute(
                    "UPDATE v22_candidate_state SET side=?,first_seen=?,last_seen=?,streak=?,best_score=?,last_reason=? WHERE symbol=?",
                    (side, first, now, streak, max(score, safe_float(row["best_score"], 0)), "", symbol),
                )
                return {
                    "streak": streak,
                    "age_min": round((now - first) / 60.0, 1),
                    "persistent": streak >= 2 and (now - first) <= V22_CANDIDATE_MEMORY_MINUTES * 60,
                }
        except Exception as exc:
            LOGGER.debug("V22 persistence failed %s: %s", symbol, exc)
            return {"streak": 1, "age_min": 0.0, "persistent": False}

    def evaluate(self, item: dict[str, Any], learning: TitanLearningEngineV22) -> dict[str, Any]:
        symbol = str(item.get("symbol") or "")
        v21 = item.get("trust_max_v21") or {}
        data = v21.get("data_integrity") or {}
        regime = v21.get("regime") or {}
        cns = item.get("cognitive_nexus") or {}
        quality = safe_float(item.get("signal_quality"), 0)
        neural = item.get("neural_v9") or {}
        neural_conf = safe_float(neural.get("confidence"), 0)
        rr = safe_float(item.get("effective_rr_tp1"), safe_float(item.get("rr_tp1"), 0))
        ai_side, ai_agree = self._ai(item)
        edges = self._candidate_edges(item)

        # Add AI only as a weighted partner. Historical AI performance can move
        # this influence, but never above a bounded ceiling.
        prof_long = learning.side_profile(symbol, "LONG")
        prof_short = learning.side_profile(symbol, "SHORT")
        chosen = "LONG" if edges["LONG"] >= edges["SHORT"] else "SHORT"
        prof = prof_long if chosen == "LONG" else prof_short
        global_prof = learning.global_profile()

        ai_bonus = 0.0
        if ai_side == chosen:
            base_ai = 4.0 + ai_agree * 0.07
            if prof.get("ai_samples", 0) >= 8:
                ai_quality = prof.get("ai_aligned_wr", 50)
                base_ai *= clamp(0.75 + (ai_quality - 45) / 80.0, 0.65, 1.35)
            ai_bonus = min(10.0, base_ai)
        elif ai_side in {"LONG", "SHORT"} and ai_agree >= 65:
            ai_bonus = -min(9.0, ai_agree * 0.06)

        score = clamp(max(edges.values()) + ai_bonus, 0, 100)
        raw_margin = edges["LONG"] - edges["SHORT"]
        # Never resolve an exact/near tie into SHORT merely because of a Python
        # else branch. A direction requires a measurable edge over the other side.
        side = "LONG" if raw_margin >= 1.0 else "SHORT" if raw_margin <= -1.0 else "WAIT"
        margin = abs(raw_margin)

        history_shift = prof.get("threshold_shift", 0.0)
        promote_threshold = V22_PROMOTE_SCORE + history_shift
        if prof.get("samples", 0) >= 20 and prof.get("recent_win_rate", 50) >= 60:
            promote_threshold -= 2.0
        # Balanced band: allow real edges through; history can still raise the bar a bit.
        promote_threshold = clamp(promote_threshold, 52.0, 72.0)

        hard_vetoes = []
        hard_vetoes.extend(data.get("hard_fail") or [])
        # Soften: only keep the most severe CNS vetoes as hard blockers
        for v in (cns.get("vetoes") or []):
            if str(v) in {"data_quality", "ai_hard_conflict", "rr"}:
                hard_vetoes.append(v)
        if rr < V22_MIN_RR:
            hard_vetoes.append("RR")
        if ai_side in {"LONG", "SHORT"} and ai_side != side and ai_agree >= V22_MAX_AI_CONFLICT:
            hard_vetoes.append("AI_HARD_CONFLICT")
        # Allow at most V22_MAX_HARD_VETOES soft issues without killing the signal
        if len(hard_vetoes) > max(0, int(V22_MAX_HARD_VETOES)):
            pass  # keep list; trigger logic still checks emptiness for strongest path
        else:
            # With balanced mode, a single mild veto does not zero the opportunity
            hard_vetoes = [v for v in hard_vetoes if str(v) in {"data_quality", "AI_HARD_CONFLICT", "invalid_price"}]

        persistence = self._persistence(symbol, side, score)

        # A strong candidate can be promoted on the first scan; otherwise two
        # consecutive observations are required. This is the anti-noise hysteresis.
        strong_trigger = (
            side in {"LONG", "SHORT"}
            and score >= V22_STRONG_TRIGGER_SCORE
            and data.get("trust", 0) >= V22_MIN_DATA
            and quality >= V22_MIN_QUALITY
            and neural_conf >= V22_MIN_NEURAL
            and rr >= V22_MIN_RR
            and len(hard_vetoes) <= V22_MAX_HARD_VETOES
            and ai_agree < V22_MAX_AI_CONFLICT
        )
        stable_trigger = (
            side in {"LONG", "SHORT"}
            and score >= promote_threshold
            and margin >= 3.5
            and data.get("trust", 0) >= V22_MIN_DATA
            and quality >= V22_MIN_QUALITY
            and neural_conf >= V22_MIN_NEURAL
            and rr >= V22_MIN_RR
            and (persistence["persistent"] or score >= V22_STRONG_TRIGGER_SCORE - 2)
            and len(hard_vetoes) <= V22_MAX_HARD_VETOES
        )

        core_decision = _v21_direction(item.get("decision_tag"))
        action = core_decision
        promoted = False
        if core_decision == "WAIT" and (strong_trigger or stable_trigger):
            action = side
            promoted = True

        # If the core already has a directional decision, V22 never changes its
        # direction merely because AI is louder; it only verifies/grades it.
        if core_decision in {"LONG", "SHORT"}:
            side = core_decision

        if action in {"LONG", "SHORT"}:
            state = "READY" if (data.get("trust", 0) >= 80 and quality >= 72 and neural_conf >= 65 and rr >= 1.35) else "EARLY"
        elif side in {"LONG", "SHORT"} and score >= V22_EARLY_SCORE and not hard_vetoes:
            state = "EARLY_" + side
        elif side in {"LONG", "SHORT"} and score >= V22_WATCH_SCORE:
            state = "WATCH_" + side
        else:
            state = "NO_EDGE"

        # Complete reason tree — every positive/negative contribution is visible.
        reasons = []
        reasons.append(f"سمت کاندید: {side}")
        reasons.append(f"امتیاز فرصت: {score:.1f}/100")
        reasons.append(f"اختلاف دو سمت: {margin:.1f}")
        reasons.append(f"اعتماد داده: {safe_float(data.get('trust'),0):.1f}")
        reasons.append(f"کیفیت سیگنال: {quality:.1f}")
        reasons.append(f"اعتماد عصبی: {neural_conf:.1f}")
        reasons.append(f"RR1: {rr:.2f}")
        reasons.append(f"رأی AI: {ai_side} با توافق {ai_agree:.1f}%")
        reasons.append(f"پایداری کاندید: {persistence['streak']} اسکن / {persistence['age_min']:.1f} دقیقه")
        reasons.append(f"رژیم: {regime.get('regime','—')}")
        if hard_vetoes:
            reasons.append("موانع سخت: " + ", ".join(dict.fromkeys(hard_vetoes)))
        if promoted:
            reasons.append("فرصت WAIT به سیگنال ارتقا یافت چون آستانه فرصت + شواهد مستقل + پایداری/تریگر برقرار شد")
        elif core_decision == "WAIT" and state.startswith(("EARLY_", "WATCH_")):
            reasons.append("سیگنال نهایی هنوز WAIT است؛ فرصت پنهان نشده و به‌عنوان پیش‌هشدار ثبت شد")
        elif core_decision == "WAIT":
            reasons.append("شواهد برای جهت‌دهی نهایی کافی نیست")

        return {
            "version": V22_VERSION,
            "action": action,
            "core_action": core_decision,
            "candidate_side": side,
            "opportunity_state": state,
            "opportunity_score": round(score, 1),
            "margin": round(margin, 1),
            "edges": {k: round(v, 1) for k, v in edges.items()},
            "ai": {"majority": ai_side, "agreement": round(ai_agree, 1), "bonus": round(ai_bonus, 2)},
            "learning": {
                "chosen_side": prof,
                "global": global_prof,
                "threshold": round(promote_threshold, 1),
            },
            "persistence": persistence,
            "hard_vetoes": list(dict.fromkeys(hard_vetoes)),
            "promoted": promoted,
            "reason_tree": reasons,
            "balance": {
                "actionable": action in {"LONG", "SHORT"},
                "opportunity_visible": state != "NO_EDGE",
                "false_signal_protection": bool(hard_vetoes or not promoted),
            },
        }


class TitanDecisionAuditV22:
    """Persistent decision ledger and self-review metrics."""

    def record(self, item: dict[str, Any], opp: dict[str, Any]) -> None:
        try:
            now = time.time()
            symbol = str(item.get("symbol") or "")
            with DB_LOCK, db_conn() as con:
                recent = con.execute(
                    "SELECT 1 FROM decision_journal_v22 WHERE symbol=? AND created_at>? LIMIT 1",
                    (symbol, now - V22_JOURNAL_COOLDOWN),
                ).fetchone()
                if recent:
                    return
                fusion = item.get("fusion") or {}
                con.execute(
                    "INSERT INTO decision_journal_v22("
                    "created_at,symbol,decision,candidate_side,opportunity_state,opportunity_score,"
                    "trust,quality,ai_majority,ai_agreement,regime,reason_json,outcome"
                    ") VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",
                    (
                        now, symbol, str(item.get("decision_tag") or "WAIT"),
                        opp.get("candidate_side","WAIT"),
                        opp.get("opportunity_state","NO_EDGE"),
                        safe_float(opp.get("opportunity_score"),0),
                        safe_float((item.get("trust_max_v21") or {}).get("trust"),0),
                        safe_float(item.get("signal_quality"),0),
                        str((opp.get("ai") or {}).get("majority","WAIT")),
                        safe_float((opp.get("ai") or {}).get("agreement"),0),
                        str((opp.get("regime") or {}).get("regime") or (item.get("trust_max_v21") or {}).get("regime",{}).get("regime","")),
                        json.dumps({"reasons": opp.get("reason_tree",[]), "edges": opp.get("edges",{}), "learning": opp.get("learning",{})}, ensure_ascii=False),
                        "PENDING",
                    ),
                )
        except Exception as exc:
            LOGGER.debug("V22 journal write failed %s: %s", item.get("symbol"), exc)

    def summary(self) -> dict[str, Any]:
        try:
            with DB_LOCK, db_conn() as con:
                rows = con.execute(
                    "SELECT opportunity_state,decision,outcome,opportunity_score,trust,quality,ai_majority,ai_agreement "
                    "FROM decision_journal_v22 ORDER BY created_at DESC LIMIT 1000"
                ).fetchall()
            total = len(rows)
            ready = sum(1 for r in rows if str(r["decision"]) in {"LONG","SHORT"})
            visible = sum(1 for r in rows if str(r["opportunity_state"]) != "NO_EDGE")
            pending = sum(1 for r in rows if str(r["outcome"]) == "PENDING")
            return {
                "journal_rows": total,
                "directional_decisions": ready,
                "opportunities_visible": visible,
                "pending_reviews": pending,
                "coverage_pct": round(visible / total * 100, 1) if total else 0.0,
            }
        except Exception:
            return {"journal_rows": 0, "directional_decisions": 0, "opportunities_visible": 0, "pending_reviews": 0, "coverage_pct": 0.0}


TITAN_LEARNING_V22 = TitanLearningEngineV22()
TITAN_OPPORTUNITY_V22 = TitanOpportunityEngineV22()
TITAN_AUDIT_V22 = TitanDecisionAuditV22()


_analyze_asset_v21 = analyze_asset


def analyze_asset(symbol: str, btc_trend: str) -> Optional[dict[str, Any]]:
    item = _analyze_asset_v21(symbol, btc_trend)
    if not item:
        return None
    try:
        opp = TITAN_OPPORTUNITY_V22.evaluate(item, TITAN_LEARNING_V22)

        # If V22 legitimately promotes a WAIT, rebuild levels before exposing it.
        if opp.get("promoted") and opp.get("action") in {"LONG", "SHORT"} and item.get("decision_tag") == "WAIT":
            sl, tp1, tp2 = _v12_rebuild_directional_levels(item, opp["action"])
            price = _v12_parse_price(item.get("price"))
            chk = _v12_level_integrity(price, sl, tp1, tp2, opp["action"])
            if chk.get("ok"):
                item["stop_loss"] = smart_format(sl)
                item["tp1"] = smart_format(tp1)
                item["tp2"] = smart_format(tp2)
                item["effective_rr_tp1"] = chk["rr1"]
                item["effective_rr_tp2"] = chk["rr2"]
                item["rr_tp1"] = chk["rr1"]
                item["rr_tp2"] = chk["rr2"]
                item["decision_tag"] = opp["action"]
                item["bias"] = "صعودی" if opp["action"] == "LONG" else "نزولی"
                item["signal_tag"] = "V22 ADAPTIVE OPPORTUNITY"
                item["entry_mode"] = "EARLY"
                item.setdefault("fusion", {})["v22_promotion"] = True
                opp["level_integrity"] = chk
            else:
                opp["promoted"] = False
                opp["action"] = "WAIT"
                opp["level_integrity"] = chk
                opp["reason_tree"].append("ارتقا لغو شد چون SL/TP/RR نهایی معتبر نبود")

        # If V22 does not promote, preserve the real V21 decision but expose
        # the opportunity state so a strong setup is not hidden as a blank WAIT.
        item["opportunity_v22"] = opp
        item.setdefault("fusion", {})["opportunity_v22"] = opp
        item["decision_audit_v22"] = {
            "decision": item.get("decision_tag","WAIT"),
            "core_decision": opp.get("core_action","WAIT"),
            "candidate_side": opp.get("candidate_side","WAIT"),
            "state": opp.get("opportunity_state","NO_EDGE"),
            "score": opp.get("opportunity_score",0),
            "margin": opp.get("margin",0),
            "reasons": opp.get("reason_tree",[]),
            "learning": opp.get("learning",{}),
            "ai": opp.get("ai",{}),
        }
        item["opportunity_score"] = opp.get("opportunity_score",0)
        item["opportunity_state"] = opp.get("opportunity_state","NO_EDGE")
        item["opportunity_side"] = opp.get("candidate_side","WAIT")
        item["decision_reason"] = " | ".join(opp.get("reason_tree",[])[:12])

        # Final integrity: bias ↔ decision_tag ↔ grade stay coherent for the UI
        dec = str(item.get("decision_tag") or "WAIT").upper()
        if dec == "LONG":
            item["bias"] = "صعودی"
        elif dec == "SHORT":
            item["bias"] = "نزولی"
        elif dec == "WAIT":
            if item.get("bias") in {"صعودی", "نزولی"} and safe_float(item.get("opportunity_score"), 0) < 48:
                item["bias"] = "خنثی"
        # Ensure grade string is always present for templates
        if not item.get("grade"):
            sg = item.get("signal_grade") or {}
            item["grade"] = sg.get("grade") or "—"
            item["trust_index"] = item.get("trust_index") or sg.get("trust_index") or 0
        # Clamp display probability
        try:
            item["success_probability"] = round(float(clamp(safe_float(item.get("success_probability"), 50), 1, 95)), 1)
        except Exception:
            item["success_probability"] = 50.0
        item["param_version"] = TITAN_PARAM_VERSION

        TITAN_AUDIT_V22.record(item, opp)
        return item
    except Exception as exc:
        LOGGER.exception("V22 adaptive opportunity failed for %s: %s", symbol, exc)
        item["opportunity_v22"] = {
            "version": V22_VERSION,
            "action": item.get("decision_tag","WAIT"),
            "opportunity_state": "UNKNOWN",
            "opportunity_score": 0,
            "reason_tree": ["V22 خطا داد؛ تصمیم هسته بدون تغییر حفظ شد"],
        }
        return item


